### Co nahrát na ESP32 (kód a postup)

Pro zprovoznění budete potřebovat **Arduino IDE** s nainstalovanou podporou pro ESP32. Poskytnu vám kompletní, okomentovaný kód.

#### 1. Požadavky na hardware
*   Deska ESP32 (např. ESP32 DevKitC)
*   RFID čtečka MFRC522
*   Propojovací vodiče
*   (Volitelně, ale doporučeno) 5V relé modul pro ovládání zámku
*   (Volitelně) Zelená a červená LED pro signalizaci stavu

#### 2. Zapojení (ESP32 ↔ MFRC522)
Toto je standardní zapojení přes SPI sběrnici. **Dávejte pozor, MFRC522 je 3.3V zařízení, stejně jako ESP32, takže je můžete propojit přímo.**

| Pin na MFRC522 | Pin na ESP32 | Popis              |
| :------------- | :----------- | :----------------- |
| **SDA (SS)**   | **GPIO 5**   | Chip Select        |
| **SCK**        | **GPIO 18**  | Serial Clock       |
| **MOSI**       | **GPIO 23**  | Master Out Slave In|
| **MISO**       | **GPIO 19**  | Master In Slave Out|
| **RST**        | **GPIO 4**   | Reset              |
| **GND**        | **GND**      | Zem                |
| **3.3V**       | **3V3**      | Napájení           |

#### 3. Kód pro Arduino IDE
Tento kód zkopírujte a vložte do nového projektu v Arduino IDE.

**Než ho nahrajete, musíte nainstalovat potřebné knihovny:**
1.  V Arduino IDE jděte do `Nástroje` -> `Správce knihoven...`.
2.  Vyhledejte a nainstalujte následující knihovny:
    *   `MFRC522` od `miguelbalboa` (nebo `GitHubCommunity`)
    *   `ArduinoJson` od `bblanchon`

```cpp
#include <SPI.h>
#include <MFRC522.h>
#include <WiFi.h>
#include <HTTPClient.h>
#include <ArduinoJson.h>

// -------- NASTAVENÍ UŽIVATELE --------
const char* WIFI_SSID = "NAZEV_VASI_WIFI";       // <-- Zadejte název vaší Wi-Fi
const char* WIFI_PASSWORD = "HESLO_K_VASI_WIFI"; // <-- Zadejte heslo k vaší Wi-Fi

const char* SERVER_IP = "192.168.1.105"; // <-- Zadejte IP adresu počítače, kde běží Flask server
const int SERVER_PORT = 5000;

// Definice pinů pro MFRC522
#define SS_PIN    5
#define RST_PIN   4

// Definice pinů pro výstupy
#define RELAY_PIN 2         // Pin pro relé (ovládání zámku)
#define GREEN_LED_PIN 16    // Zelená LED pro povolený přístup
#define RED_LED_PIN   17    // Červená LED pro zamítnutý přístup
// ------------------------------------

MFRC522 mfrc522(SS_PIN, RST_PIN);  // Vytvoření instance MFRC522

void initWiFi() {
  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
  Serial.print("Connecting to WiFi ..");
  while (WiFi.status() != WL_CONNECTED) {
    Serial.print('.');
    delay(1000);
  }
  Serial.println("\nConnected!");
  Serial.print("IP Address: ");
  Serial.println(WiFi.localIP());
}

void setup() {
  Serial.begin(115200);
  SPI.begin();
  mfrc522.PCD_Init();

  pinMode(RELAY_PIN, OUTPUT);
  pinMode(GREEN_LED_PIN, OUTPUT);
  pinMode(RED_LED_PIN, OUTPUT);

  digitalWrite(RELAY_PIN, LOW); // Ujistíme se, že relé je na začátku vypnuté
  digitalWrite(GREEN_LED_PIN, LOW);
  digitalWrite(RED_LED_PIN, LOW);

  initWiFi();

  Serial.println("\nRFID Access Control Ready. Please scan a card.");
}

void loop() {
  // Pokud není přítomna nová karta, nic nedělej
  if (!mfrc522.PICC_IsNewCardPresent() || !mfrc522.PICC_ReadCardSerial()) {
    delay(50);
    return;
  }

  Serial.print("Card UID:");
  String chipId = "";
  for (byte i = 0; i < mfrc522.uid.size; i++) {
    Serial.print(mfrc522.uid.uidByte[i] < 0x10 ? " 0" : " ");
    Serial.print(mfrc522.uid.uidByte[i], HEX);
    chipId += (mfrc522.uid.uidByte[i] < 0x10 ? "0" : "");
    chipId += String(mfrc522.uid.uidByte[i], HEX);
  }
  chipId.toUpperCase();
  Serial.println();
  Serial.println("Chip ID to send: " + chipId);

  // Odešli ID čipu na server
  sendChipIdToServer(chipId);

  // Zastav čtení, aby se stejná karta nečetla znovu a znovu
  mfrc522.PICC_HaltA();
  mfrc522.PCD_StopCrypto1();

  // Krátká pauza, než bude možné číst další kartu
  delay(2000);
}

void sendChipIdToServer(String chipId) {
  if (WiFi.status() == WL_CONNECTED) {
    HTTPClient http;
    String serverUrl = "http://" + String(SERVER_IP) + ":" + String(SERVER_PORT) + "/api/check-access";

    http.begin(serverUrl);
    http.addHeader("Content-Type", "application/json");

    // Vytvoření JSONu
    StaticJsonDocument<200> doc;
    doc["chip_id"] = chipId;
    String jsonPayload;
    serializeJson(doc, jsonPayload);

    // Odeslání POST požadavku
    int httpResponseCode = http.POST(jsonPayload);

    if (httpResponseCode > 0) {
      String response = http.getString();
      Serial.println("HTTP Response code: " + String(httpResponseCode));
      Serial.println("Response: " + response);

      // Zpracování odpovědi
      StaticJsonDocument<200> responseDoc;
      deserializeJson(responseDoc, response);
      const char* status = responseDoc["status"];

      if (strcmp(status, "GRANTED") == 0) {
        Serial.println("Access GRANTED");
        triggerDoorUnlock();
      } else {
        Serial.println("Access DENIED");
        signalDenial();
      }

    } else {
      Serial.print("Error on sending POST: ");
      Serial.println(httpResponseCode);
      signalDenial(); // Signalizuj chybu i při selhání komunikace
    }

    http.end();
  } else {
    Serial.println("WiFi Disconnected");
    // Zkus se znovu připojit
    initWiFi();
  }
}

void triggerDoorUnlock() {
  digitalWrite(GREEN_LED_PIN, HIGH);
  digitalWrite(RELAY_PIN, HIGH); // Sepni relé (odemkni)
  delay(3000); // Dveře zůstanou odemčené 3 sekundy
  digitalWrite(RELAY_PIN, LOW);  // Vypni relé (zamkni)
  digitalWrite(GREEN_LED_PIN, LOW);
}

void signalDenial() {
  digitalWrite(RED_LED_PIN, HIGH);
  delay(2000); // Červená LED svítí 2 sekundy
  digitalWrite(RED_LED_PIN, LOW);
}

```

#### 4. Jak nahrát kód
1.  Otevřete Arduino IDE.
2.  Nainstalujte podporu pro desky ESP32 (pokud ji ještě nemáte). V `Soubor` -> `Vlastnosti` přidejte do "Additional Boards Manager URLs" tento odkaz: `https://raw.githubusercontent.com/espressif/arduino-esp32/gh-pages/package_esp32_index.json`. Poté v `Nástroje` -> `Vývojová deska` -> `Správce desek` vyhledejte a nainstalujte "esp32".
3.  Zkopírujte výše uvedený kód do IDE.
4.  **Upravte konfigurační sekci na začátku kódu:**
    *   `WIFI_SSID` a `WIFI_PASSWORD` nahraďte údaji vaší Wi-Fi sítě.
    *   `SERVER_IP` nahraďte **lokální IP adresou počítače**, na kterém běží vaše Flask aplikace (`app.py`). Tuto adresu zjistíte na Windows příkazem `ipconfig` a na macOS/Linux příkazem `ifconfig` nebo `ip a`.
5.  Připojte ESP32 k počítači přes USB.
6.  V `Nástroje` -> `Vývojová deska` vyberte vaši desku (např. "ESP32 Dev Module").
7.  V `Nástroje` -> `Port` vyberte správný COM port, ke kterému je ESP32 připojeno.
8.  Klikněte na tlačítko "Nahrát" (šipka doprava).

Po nahrání otevřete Sériový monitor (`Ctrl+Shift+M`), abyste viděli ladicí výpisy. Měli byste vidět, jak se ESP32 připojuje k Wi-Fi a je připraveno ke skenování.

Samozřejmě, rád to vysvětlím. Funkce "Načíst ze čtečky" je navržena tak, aby zjednodušila přidávání nových čipů a eliminovala nutnost ručního opisování jejich ID.

Mechanismus je trochu jiný než u ESP32, který komunikuje přes Wi-Fi. Zde se využívá přímá komunikace přes USB kabel mezi Arduinem a počítačem, na kterém běží váš server (Flask aplikace).

### Jak to funguje: Kroky komunikace

1.  **Stisknutí tlačítka:** V prohlížeči kliknete na tlačítko "Načíst ze čtečky".
2.  **Frontendový požadavek:** Váš prohlížeč (JavaScript) pošle **HTTP GET požadavek** na adresu `/scan` vašeho lokálního serveru (např. `http://localhost:5000/scan`).
3.  **Backend (Flask) naslouchá:** Vaše Flask aplikace v `app.py` obdrží tento požadavek. Endpoint `/scan` je speciálně naprogramován tak, aby na několik sekund začal naslouchat na **sériovém portu (USB)**, ke kterému je připojeno vaše Arduino.
4.  **Arduino odesílá data:** Arduino, které má neustále aktivní čtečku RDM6300, čeká na přiložení čipu. Jakmile čip přečte, jeho ID okamžitě pošle přes USB sériovou linku do počítače.
5.  **Backend zachytí ID:** Flask aplikace přečte data (ID čipu) přicházející z Arduina.
6.  **Odpověď na Frontend:** Server zabalí toto ID do JSON formátu (např. `{"chip_id": "0008620059"}`) a pošle ho jako odpověď zpět prohlížeči.
7.  **Vyplnění pole:** JavaScript v prohlížeči přijme odpověď a automaticky vyplní pole "ID čipu" v modálním okně.

