@app.route('/scan', methods=['GET'])
def scan_chip():
    try:
        with serial.Serial(SERIAL_PORT, SERIAL_BAUDRATE, timeout=SERIAL_TIMEOUT) as ser:
            # Krátká pauza, aby se port stihl inicializovat
            time.sleep(2)
            line = ser.readline()
            if line:
                # Dekódování z bytů na string a odstranění bílých znaků
                chip_id = line.decode('utf-8').strip()
                return jsonify({'chip_id': chip_id})
            else:
                return jsonify({'error': 'Timeout: Žádný čip nebyl přiložen v časovém limitu.'}), 408
    except serial.SerialException as e:
        return jsonify({'error': f'Chyba sériového portu: {e}. Zkontrolujte připojení a název portu.'}), 500
    except Exception as e:
        return jsonify({'error': f'Nastala neočekávaná chyba: {e}'}), 500

