@app.route('/api/check-access', methods=['POST'])
def check_access():
    data = request.json
    chip_id = data.get('chip_id')

    if not chip_id:
        return jsonify({'status': 'DENIED', 'reason': 'NO_CHIP_ID'}), 400

    # Speciální případ pro manuální odemčení z dashboardu
    if chip_id == 'MANUAL_OVERRIDE':
        log = AccessLog(chip_id='MANUAL_OVERRIDE', name='Admin', result='GRANTED')
        db.session.add(log)
        db.session.commit()
        return jsonify({'status': 'GRANTED', 'name': 'Admin'})

    chip = Chip.query.filter_by(chip_id=chip_id).first()

    if not chip:
        log = AccessLog(chip_id=chip_id, name='Unknown', result='DENIED (UNKNOWN)')
        db.session.add(log)
        db.session.commit()
        return jsonify({'status': 'DENIED', 'reason': 'UNKNOWN_CHIP'})

    if not chip.is_allowed:
        log = AccessLog(chip_id=chip_id, name=chip.name, result='DENIED (BLOCKED)')
        db.session.add(log)
        db.session.commit()
        return jsonify({'status': 'DENIED', 'reason': 'CHIP_BLOCKED'})

    if chip.valid_until and datetime.utcnow() > chip.valid_until:
        log = AccessLog(chip_id=chip_id, name=chip.name, result='DENIED (EXPIRED)')
        db.session.add(log)
        db.session.commit()
        return jsonify({'status': 'DENIED', 'reason': 'CHIP_EXPIRED'})

    # Pokud je čip jednorázový, po úspěšném použití ho zablokujeme
    if chip.is_one_time:
        chip.is_allowed = False

    log = AccessLog(chip_id=chip_id, name=chip.name, result='GRANTED')
    db.session.add(log)
    db.session.commit()

    return jsonify({'status': 'GRANTED', 'name': chip.name})


