import os
from flask import Flask, jsonify, request, send_from_directory
from flask_sqlalchemy import SQLAlchemy
from flask_cors import CORS
from datetime import datetime, timedelta
import serial
import time

# --- Configuration ---
# Adjust the COM port based on where your Arduino for chip scanning is connected
SERIAL_PORT = 'COM3'  # For Windows (e.g., 'COM3')
# SERIAL_PORT = '/dev/tty.usbmodem14201' # For macOS/Linux
SERIAL_BAUDRATE = 9600
SERIAL_TIMEOUT = 5  # 5 seconds to present the chip

# --- App Initialization ---
app = Flask(__name__, static_folder='dist', static_url_path='/')
CORS(app)

# Database Configuration
basedir = os.path.abspath(os.path.dirname(__file__))
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///' + os.path.join(basedir, 'system.db')
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False
db = SQLAlchemy(app)

# --- Database Models ---
class Chip(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    chip_id = db.Column(db.String(100), unique=True, nullable=False)
    name = db.Column(db.String(100), nullable=False)
    is_allowed = db.Column(db.Boolean, default=True)
    is_one_time = db.Column(db.Boolean, default=False)
    valid_until = db.Column(db.DateTime, nullable=True)

class AccessLog(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    timestamp = db.Column(db.DateTime, default=datetime.utcnow)
    chip_id = db.Column(db.String(100), nullable=False)
    name = db.Column(db.String(100), nullable=False)
    result = db.Column(db.String(50), nullable=False)

# --- Helper Functions ---
def serialize_chip(chip):
    return {
        'id': chip.id,
        'chip_id': chip.chip_id,
        'name': chip.name,
        'is_allowed': chip.is_allowed,
        'is_one_time': chip.is_one_time,
        'valid_until': chip.valid_until.isoformat() if chip.valid_until else None,
    }

def serialize_log(log):
    return {
        'id': log.id,
        'timestamp': log.timestamp.isoformat(),
        'chip_id': log.chip_id,
        'name': log.name,
        'result': log.result,
    }

# --- API Endpoints ---

# Endpoint for scanning a chip via USB/Serial
@app.route('/scan', methods=['GET'])
def scan_chip():
    try:
        with serial.Serial(SERIAL_PORT, SERIAL_BAUDRATE, timeout=SERIAL_TIMEOUT) as ser:
            # Short pause to allow the port to initialize
            time.sleep(2)
            line = ser.readline()
            if line:
                # Decode from bytes to string and remove whitespace
                chip_id = line.decode('utf-8').strip()
                return jsonify({'chip_id': chip_id})
            else:
                return jsonify({'error': 'Timeout: No chip was presented within the time limit.'}), 408
    except serial.SerialException as e:
        return jsonify({'error': f'Serial port error: {e}. Check the connection and port name.'}), 500
    except Exception as e:
        return jsonify({'error': f'An unexpected error occurred: {e}'}), 500

# Endpoint for checking access
@app.route('/api/check-access', methods=['POST'])
def check_access():
    data = request.json
    chip_id = data.get('chip_id')

    if not chip_id:
        return jsonify({'status': 'DENIED', 'reason': 'NO_CHIP_ID'}), 400

    # Special case for manual override from the dashboard
    if chip_id == 'MANUAL_OVERRIDE':
        log = AccessLog(chip_id='MANUAL_OVERRIDE', name='Admin', result='GRANTED')
        db.session.add(log)
        db.session.commit()
        return jsonify({'status': 'GRANTED', 'name': 'Admin'})

    chip = Chip.query.filter_by(chip_id=chip_id).first()

    if not chip:
        log = AccessLog(chip_id=chip_id, name='Unknown', result='DENIED (UNKNOWN)')
        db.session.add(log)
        db.session.commit()
        return jsonify({'status': 'DENIED', 'reason': 'UNKNOWN_CHIP'})

    if not chip.is_allowed:
        log = AccessLog(chip_id=chip_id, name=chip.name, result='DENIED (BLOCKED)')
        db.session.add(log)
        db.session.commit()
        return jsonify({'status': 'DENIED', 'reason': 'CHIP_BLOCKED'})

    if chip.valid_until and datetime.utcnow() > chip.valid_until:
        log = AccessLog(chip_id=chip_id, name=chip.name, result='DENIED (EXPIRED)')
        db.session.add(log)
        db.session.commit()
        return jsonify({'status': 'DENIED', 'reason': 'CHIP_EXPIRED'})

    # If the chip is one-time, block it after successful use
    if chip.is_one_time:
        chip.is_allowed = False

    log = AccessLog(chip_id=chip_id, name=chip.name, result='GRANTED')
    db.session.add(log)
    db.session.commit()

    return jsonify({'status': 'GRANTED', 'name': chip.name})


# CRUD for chips
@app.route('/api/chips', methods=['GET', 'POST'])
def manage_chips():
    if request.method == 'GET':
        chips = Chip.query.order_by(Chip.name).all()
        return jsonify([serialize_chip(c) for c in chips])

    if request.method == 'POST':
        data = request.json
        valid_until = datetime.fromisoformat(data['valid_until'].replace('Z', '+00:00')) if data.get('valid_until') else None

        new_chip = Chip(
            chip_id=data['chip_id'],
            name=data['name'],
            is_allowed=data['is_allowed'],
            is_one_time=data['is_one_time'],
            valid_until=valid_until
        )
        db.session.add(new_chip)
        db.session.commit()
        return jsonify(serialize_chip(new_chip)), 201

@app.route('/api/chips/<int:chip_id>', methods=['PUT', 'DELETE'])
def manage_single_chip(chip_id):
    chip = Chip.query.get_or_404(chip_id)

    if request.method == 'PUT':
        data = request.json
        chip.chip_id = data['chip_id']
        chip.name = data['name']
        chip.is_allowed = data['is_allowed']
        chip.is_one_time = data['is_one_time']
        chip.valid_until = datetime.fromisoformat(data['valid_until'].replace('Z', '+00:00')) if data.get('valid_until') else None
        db.session.commit()
        return jsonify(serialize_chip(chip))

    if request.method == 'DELETE':
        db.session.delete(chip)
        db.session.commit()
        return jsonify({'message': 'Chip deleted successfully'})

# Endpoint for logs
@app.route('/api/logs', methods=['GET'])
def get_logs():
    limit = request.args.get('limit', type=int)
    query = AccessLog.query.order_by(AccessLog.timestamp.desc())
    if limit:
        query = query.limit(limit)
    logs = query.all()
    return jsonify([serialize_log(l) for l in logs])

# --- Serve Frontend App ---
@app.route('/')
def serve_index():
    return send_from_directory(app.static_folder, 'index.html')

@app.route('/<path:path>')
def serve_static(path):
    if os.path.exists(os.path.join(app.static_folder, path)):
        return send_from_directory(app.static_folder, path)
    return serve_index()

# --- Run Application ---
if __name__ == '__main__':
    with app.app_context():
        db.create_all()
    app.run(host='0.0.0.0', port=5000, debug=True)

import React, { useState, FormEvent, useEffect, useCallback } from 'react';
import { Chip } from '../types';
import { CloseIcon, ScanIcon } from './icons';

interface ChipModalProps {
    chip: Chip | null;
    onClose: () => void;
    onSave: (chip: Omit<Chip, 'id'> | Chip) => void;
}

export const ChipModal: React.FC<ChipModalProps> = ({ chip, onClose, onSave }) => {
    const [formData, setFormData] = useState({
        name: '',
        chip_id: '',
        is_allowed: true,
        is_one_time: false,
        valid_until: '',
    });
    const [isScanning, setIsScanning] = useState(false);
    const [scanError, setScanError] = useState<string | null>(null);

    useEffect(() => {
        if (chip) {
            setFormData({
                name: chip.name,
                chip_id: chip.chip_id,
                is_allowed: chip.is_allowed,
                is_one_time: chip.is_one_time,
                valid_until: chip.valid_until ? chip.valid_until.split('T')[0] : '',
            });
        }
    }, [chip]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value, type, checked } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: type === 'checkbox' ? checked : value,
        }));
    };

    const handleScan = useCallback(async () => {
        setIsScanning(true);
        setScanError(null);
        try {
            const response = await fetch('/scan');
            const data = await response.json();

            if (!response.ok) {
                throw new Error(data.error || 'Error during scan');
            }

            if (data.chip_id) {
                setFormData(prev => ({ ...prev, chip_id: data.chip_id }));
            }
        } catch (error) {
            console.error('Scan error:', error);
            setScanError(error instanceof Error ? error.message : 'Unknown reader error');
        } finally {
            setIsScanning(false);
        }
    }, []);

    const handleSubmit = (e: FormEvent) => {
        e.preventDefault();
        const submissionData = {
            ...formData,
            valid_until: formData.valid_until ? new Date(formData.valid_until).toISOString() : null,
        };
        if (chip) {
            onSave({ ...chip, ...submissionData });
        } else {
            onSave(submissionData);
        }
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50" aria-labelledby="modal-title" role="dialog" aria-modal="true">
            <div className="bg-white dark:bg-brand-dark rounded-lg shadow-xl w-full max-w-lg mx-4">
                <form onSubmit={handleSubmit}>
                    <div className="p-6">
                        <div className="flex justify-between items-center">
                            <h2 id="modal-title" className="text-xl font-semibold text-gray-900 dark:text-white">
                                {chip ? 'Edit Chip' : 'Add New Chip'}
                            </h2>
                            <button type="button" onClick={onClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200">
                                <CloseIcon />
                            </button>
                        </div>
                        <div className="mt-6 space-y-4">
                            <div>
                                <label htmlFor="name" className="block text-sm font-medium text-gray-700 dark:text-gray-300">Holder's Name</label>
                                <input type="text" name="name" id="name" value={formData.name} onChange={handleChange} required className="mt-1 block w-full px-3 py-2 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:outline-none focus:ring-primary-500 focus:border-primary-500 sm:text-sm" />
                            </div>
                            <div>
                                <label htmlFor="chip_id" className="block text-sm font-medium text-gray-700 dark:text-gray-300">Chip ID</label>
                                <div className="mt-1 flex gap-2">
                                    <input 
                                        type="text" 
                                        name="chip_id" 
                                        id="chip_id" 
                                        value={formData.chip_id} 
                                        onChange={handleChange} 
                                        required 
                                        className="block w-full px-3 py-2 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:outline-none focus:ring-primary-500 focus:border-primary-500 sm:text-sm font-mono" 
                                    />
                                    <button
                                        type="button"
                                        onClick={handleScan}
                                        disabled={isScanning}
                                        className={`flex items-center gap-2 px-4 py-2 text-sm font-medium text-white rounded-md transition-all ${
                                            isScanning 
                                            ? 'bg-gray-400 cursor-not-allowed' 
                                            : 'bg-primary-600 hover:bg-primary-700 active:scale-95'
                                        }`}
                                    >
                                        <ScanIcon className={`h-4 w-4 ${isScanning ? 'animate-pulse' : ''}`} />
                                        {isScanning ? 'Scanning...' : 'Scan from Reader'}
                                    </button>
                                </div>
                                {scanError && <p className="mt-1 text-xs text-red-500 font-medium">{scanError}</p>}
                                {isScanning && <p className="mt-1 text-xs text-primary-500 font-medium animate-pulse">Place chip near reader...</p>}
                            </div>
                            <div>
                                <label htmlFor="valid_until" className="block text-sm font-medium text-gray-700 dark:text-gray-300">Valid Until (optional)</label>
                                <input type="date" name="valid_until" id="valid_until" value={formData.valid_until} onChange={handleChange} className="mt-1 block w-full px-3 py-2 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm focus:outline-none focus:ring-primary-500 focus:border-primary-500 sm:text-sm" />
                            </div>
                            <div className="flex items-center space-x-8">
                                <div className="flex items-start">
                                    <div className="flex items-center h-5">
                                        <input id="is_allowed" name="is_allowed" type="checkbox" checked={formData.is_allowed} onChange={handleChange} className="focus:ring-primary-500 h-4 w-4 text-primary-600 border-gray-300 rounded" />
                                    </div>
                                    <div className="ml-3 text-sm">
                                        <label htmlFor="is_allowed" className="font-medium text-gray-700 dark:text-gray-300">Allow Access</label>
                                    </div>
                                </div>
                                <div className="flex items-start">
                                    <div className="flex items-center h-5">
                                        <input id="is_one_time" name="is_one_time" type="checkbox" checked={formData.is_one_time} onChange={handleChange} className="focus:ring-primary-500 h-4 w-4 text-primary-600 border-gray-300 rounded" />
                                    </div>
                                    <div className="ml-3 text-sm">
                                        <label htmlFor="is_one_time" className="font-medium text-gray-700 dark:text-gray-300">One-Time Chip</label>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                    <div className="bg-gray-50 dark:bg-gray-700 px-6 py-4 flex justify-end space-x-3">
                        <button type="button" onClick={onClose} className="px-4 py-2 text-sm font-medium text-gray-700 bg-white dark:bg-gray-600 dark:text-gray-200 border border-gray-300 dark:border-gray-500 rounded-md hover:bg-gray-50 dark:hover:bg-gray-500 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500">
                            Cancel
                        </button>
                        <button type="submit" className="px-4 py-2 text-sm font-medium text-white bg-primary-600 border border-transparent rounded-md shadow-sm hover:bg-primary-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500">
                            Save Chip
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
};

import React, { useMemo, useState } from 'react';
import { AccessLog, AccessResult } from '../types';
import { RefreshIcon } from './icons';

interface LogsViewerProps {
    logs: AccessLog[];
    onRefresh: () => void;
}

export const LogsViewer: React.FC<LogsViewerProps> = ({ logs, onRefresh }) => {
    const [filter, setFilter] = useState('');
    const [selectedUser, setSelectedUser] = useState('all');
    const [selectedDate, setSelectedDate] = useState('');

    const users = useMemo(() => {
        const userSet = new Set(logs.map(log => log.name));
        return ['All Users', ...Array.from(userSet).sort()];
    }, [logs]);

    const filteredLogs = useMemo(() => {
        return logs.filter(log => {
            const logDate = new Date(log.timestamp).toISOString().split('T')[0];

            // Date filter
            if (selectedDate && logDate !== selectedDate) {
                return false;
            }
            // User filter
            if (selectedUser !== 'all' && log.name !== selectedUser) {
                return false;
            }
            // Text search filter
            const searchTerm = filter.toLowerCase();
            if (searchTerm && 
                !log.name.toLowerCase().includes(searchTerm) &&
                !log.chip_id.toLowerCase().includes(searchTerm) &&
                !log.result.toLowerCase().includes(searchTerm)
            ) {
                return false;
            }
            return true;
        });
    }, [logs, filter, selectedUser, selectedDate]);

    const handleClearFilters = () => {
        setFilter('');
        setSelectedUser('all');
        setSelectedDate('');
    };

    const getResultColor = (result: AccessResult) => {
        switch (result) {
            case AccessResult.GRANTED:
                return 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-300';
            case AccessResult.DENIED_BLOCKED:
            case AccessResult.DENIED_EXPIRED:
            case AccessResult.DENIED_UNKNOWN:
                return 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-300';
            default:
                return 'bg-gray-100 text-gray-800 dark:bg-gray-900 dark:text-gray-300';
        }
    };

    return (
        <div>
            <h1 className="text-3xl font-bold text-gray-800 dark:text-white mb-6">Access Logs</h1>
            <div className="mb-4 flex flex-wrap items-center gap-4">
                <input
                    type="text"
                    placeholder="Search logs..."
                    value={filter}
                    onChange={e => setFilter(e.target.value)}
                    className="w-full sm:w-auto flex-grow max-w-sm px-4 py-2 bg-white border border-gray-300 rounded-lg dark:bg-gray-700 dark:border-gray-600 focus:outline-none focus:ring-2 focus:ring-primary-500"
                />
                <select 
                    value={selectedUser} 
                    onChange={e => setSelectedUser(e.target.value)}
                    className="w-full sm:w-auto px-4 py-2 bg-white border border-gray-300 rounded-lg dark:bg-gray-700 dark:border-gray-600 focus:outline-none focus:ring-2 focus:ring-primary-500"
                >
                    {users.map(user => (
                        <option key={user} value={user}>{user === 'all' ? 'All Users' : user}</option>
                    ))}
                </select>
                <input
                    type="date"
                    value={selectedDate}
                    onChange={e => setSelectedDate(e.target.value)}
                    className="w-full sm:w-auto px-4 py-2 bg-white border border-gray-300 rounded-lg dark:bg-gray-700 dark:border-gray-600 focus:outline-none focus:ring-2 focus:ring-primary-500"
                />
                 <button onClick={handleClearFilters} className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-200 rounded-lg hover:bg-gray-300 dark:bg-gray-600 dark:text-gray-200 dark:hover:bg-gray-500">
                    Clear Filters
                </button>
                <button onClick={onRefresh} className="p-2 ml-auto rounded-full text-gray-500 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors">
                    <RefreshIcon className="h-5 w-5"/>
                </button>
            </div>
            <div className="bg-white dark:bg-brand-dark rounded-lg shadow-md overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left text-gray-500 dark:text-gray-400">
                        <thead className="text-xs text-gray-700 uppercase bg-gray-50 dark:bg-gray-700 dark:text-gray-400">
                            <tr>
                                <th scope="col" className="px-6 py-3">Timestamp</th>
                                <th scope="col" className="px-6 py-3">Name</th>
                                <th scope="col" className="px-6 py-3">Chip ID</th>
                                <th scope="col" className="px-6 py-3">Result</th>
                            </tr>
                        </thead>
                        <tbody>
                            {filteredLogs.length > 0 ? filteredLogs.map((log) => (
                                <tr key={log.id} className="bg-white border-b dark:bg-brand-dark dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-600">
                                    <td className="px-6 py-4">{new Date(log.timestamp).toLocaleString()}</td>
                                    <td className="px-6 py-4 font-medium text-gray-900 whitespace-nowrap dark:text-white">{log.name}</td>
                                    <td className="px-6 py-4 font-mono">{log.chip_id}</td>
                                    <td className="px-6 py-4">
                                        <span className={`px-2 py-1 text-xs font-semibold rounded-full ${getResultColor(log.result)}`}>
                                            {log.result}
                                        </span>
                                    </td>
                                </tr>
                            )) : (
                                <tr>
                                    <td colSpan={4} className="px-6 py-4 text-center text-gray-500 dark:text-gray-400">
                                        No logs found matching your criteria.
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

