import os
from flask import Flask, jsonify, request, send_from_directory
from flask_sqlalchemy import SQLAlchemy
from flask_cors import CORS
from datetime import datetime, time as time_obj
import serial
import time

# --- Configuration ---
# Adjust the COM port based on where your Arduino for chip scanning is connected
SERIAL_PORT = 'COM3'  # For Windows (e.g., 'COM3')
# SERIAL_PORT = '/dev/tty.usbmodem14201' # For macOS/Linux
SERIAL_BAUDRATE = 9600
SERIAL_TIMEOUT = 5  # 5 seconds to present the chip

# --- App Initialization ---
app = Flask(__name__, static_folder='dist', static_url_path='/')
CORS(app)

# Global state for manual override
MANUAL_OVERRIDE_REQUESTED = False

# Database Configuration
basedir = os.path.abspath(os.path.dirname(__file__))
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///' + os.path.join(basedir, 'system.db')
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False
db = SQLAlchemy(app)

# --- Database Models ---
class Chip(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    chip_id = db.Column(db.String(100), unique=True, nullable=False)
    name = db.Column(db.String(100), nullable=False)
    is_allowed = db.Column(db.Boolean, default=True)
    is_one_time = db.Column(db.Boolean, default=False)
    valid_until = db.Column(db.DateTime, nullable=True)

class AccessLog(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    timestamp = db.Column(db.DateTime, default=datetime.utcnow)
    chip_id = db.Column(db.String(100), nullable=False)
    name = db.Column(db.String(100), nullable=False)
    result = db.Column(db.String(50), nullable=False)

# --- Helper Functions ---
def serialize_chip(chip):
    return {
        'id': chip.id,
        'chip_id': chip.chip_id,
        'name': chip.name,
        'is_allowed': chip.is_allowed,
        'is_one_time': chip.is_one_time,
        'valid_until': chip.valid_until.isoformat() if chip.valid_until else None,
    }

def serialize_log(log):
    return {
        'id': log.id,
        'timestamp': log.timestamp.isoformat(),
        'chip_id': log.chip_id,
        'name': log.name,
        'result': log.result,
    }

# --- API Endpoints ---

# Endpoint for scanning a chip via USB/Serial
@app.route('/scan', methods=['GET'])
def scan_chip():
    try:
        with serial.Serial(SERIAL_PORT, SERIAL_BAUDRATE, timeout=SERIAL_TIMEOUT) as ser:
            time.sleep(2)
            line = ser.readline()
            if line:
                chip_id = line.decode('utf-8').strip()
                return jsonify({'chip_id': chip_id})
            else:
                return jsonify({'error': 'Timeout: No chip was presented within the time limit.'}), 408
    except serial.SerialException as e:
        return jsonify({'error': f'Serial port error: {e}. Check the connection and port name.'}), 500
    except Exception as e:
        return jsonify({'error': f'An unexpected error occurred: {e}'}), 500

# --- Manual Override Endpoints ---
@app.route('/api/manual-override', methods=['GET'])
def manual_override():
    """Endpoint triggered by the dashboard to request a door unlock."""
    global MANUAL_OVERRIDE_REQUESTED
    MANUAL_OVERRIDE_REQUESTED = True

    # Log this administrative action
    log = AccessLog(chip_id='MANUAL_OVERRIDE', name='Admin', result='GRANTED (OVERRIDE)')
    db.session.add(log)
    db.session.commit()

    return jsonify({'status': 'OVERRIDE_REQUESTED'}), 200

@app.route('/api/override-status', methods=['GET'])
def get_override_status():
    """Endpoint polled by the hardware to check if an override is requested."""
    global MANUAL_OVERRIDE_REQUESTED

    if MANUAL_OVERRIDE_REQUESTED:
        # Reset the flag immediately after confirming to the hardware
        MANUAL_OVERRIDE_REQUESTED = False
        return jsonify({'override': True})
    else:
        return jsonify({'override': False})

# Endpoint for checking access
@app.route('/api/check-access', methods=['POST'])
def check_access():
    data = request.json
    chip_id = data.get('chip_id')

    if not chip_id:
        return jsonify({'status': 'DENIED', 'reason': 'NO_CHIP_ID'}), 400

    # The 'MANUAL_OVERRIDE' case from the dashboard is now handled by its own endpoints
    # and is no longer part of the standard access check.

    chip = Chip.query.filter_by(chip_id=chip_id).first()

    if not chip:
        log = AccessLog(chip_id=chip_id, name='Unknown', result='DENIED (UNKNOWN)')
        db.session.add(log)
        db.session.commit()
        return jsonify({'status': 'DENIED', 'reason': 'UNKNOWN_CHIP'})

    if not chip.is_allowed:
        log = AccessLog(chip_id=chip_id, name=chip.name, result='DENIED (BLOCKED)')
        db.session.add(log)
        db.session.commit()
        return jsonify({'status': 'DENIED', 'reason': 'CHIP_BLOCKED'})

    if chip.valid_until and datetime.utcnow() > chip.valid_until:
        log = AccessLog(chip_id=chip_id, name=chip.name, result='DENIED (EXPIRED)')
        db.session.add(log)
        db.session.commit()
        return jsonify({'status': 'DENIED', 'reason': 'CHIP_EXPIRED'})

    today_start = datetime.combine(datetime.utcnow().date(), time_obj.min)

    todays_entries = AccessLog.query.filter(
        AccessLog.chip_id == chip_id,
        AccessLog.result == 'GRANTED',
        AccessLog.timestamp >= today_start
    ).count()

    daily_entry_count = todays_entries + 1

    if chip.is_one_time:
        chip.is_allowed = False

    log = AccessLog(chip_id=chip_id, name=chip.name, result='GRANTED')
    db.session.add(log)
    db.session.commit()

    return jsonify({
        'status': 'GRANTED', 
        'name': chip.name,
        'daily_entry_count': daily_entry_count
    })


# CRUD for chips
@app.route('/api/chips', methods=['GET', 'POST'])
def manage_chips():
    if request.method == 'GET':
        chips = Chip.query.order_by(Chip.name).all()
        return jsonify([serialize_chip(c) for c in chips])

    if request.method == 'POST':
        data = request.json
        valid_until = datetime.fromisoformat(data['valid_until'].replace('Z', '+00:00')) if data.get('valid_until') else None

        new_chip = Chip(
            chip_id=data['chip_id'],
            name=data['name'],
            is_allowed=data['is_allowed'],
            is_one_time=data['is_one_time'],
            valid_until=valid_until
        )
        db.session.add(new_chip)
        db.session.commit()
        return jsonify(serialize_chip(new_chip)), 201

@app.route('/api/chips/<int:chip_id>', methods=['PUT', 'DELETE'])
def manage_single_chip(chip_id):
    chip = Chip.query.get_or_404(chip_id)

    if request.method == 'PUT':
        data = request.json
        chip.chip_id = data['chip_id']
        chip.name = data['name']
        chip.is_allowed = data['is_allowed']
        chip.is_one_time = data['is_one_time']
        chip.valid_until = datetime.fromisoformat(data['valid_until'].replace('Z', '+00:00')) if data.get('valid_until') else None
        db.session.commit()
        return jsonify(serialize_chip(chip))

    if request.method == 'DELETE':
        db.session.delete(chip)
        db.session.commit()
        return jsonify({'message': 'Chip deleted successfully'})

# Endpoint for logs
@app.route('/api/logs', methods=['GET'])
def get_logs():
    limit = request.args.get('limit', type=int)
    query = AccessLog.query.order_by(AccessLog.timestamp.desc())
    if limit:
        query = query.limit(limit)
    logs = query.all()
    return jsonify([serialize_log(l) for l in logs])

# --- Serve Frontend App ---
@app.route('/')
def serve_index():
    return send_from_directory(app.static_folder, 'index.html')

@app.route('/<path:path>')
def serve_static(path):
    if os.path.exists(os.path.join(app.static_folder, path)):
        return send_from_directory(app.static_folder, path)
    return serve_index()

# --- Run Application ---
if __name__ == '__main__':
    with app.app_context():
        db.create_all()
    app.run(host='0.0.0.0', port=5000, debug=True)

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Chip, AccessLog } from '../types';
import { Header } from './Header';
import { ChipManagement } from './ChipManagement';
import { LogsViewer } from './LogsViewer';
import { LockOpenIcon, RefreshIcon } from './icons';
import { Toast } from './Toast';
import { Theme } from '../App';

// The base URL of your Python Flask backend
const API_BASE_URL = ''; // Use relative paths

interface DashboardProps {
    onLogout: () => void;
    theme: Theme;
    setTheme: (theme: Theme) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ onLogout, theme, setTheme }) => {
    const [activeTab, setActiveTab] = useState<'dashboard' | 'chips' | 'logs'>('dashboard');
    const [chips, setChips] = useState<Chip[]>([]);
    const [logs, setLogs] = useState<AccessLog[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' } | null>(null);

    const latestLogId = useRef<number | null>(null);

    const showToast = (message: string, type: 'success' | 'error') => {
        setToast({ message, type });
    };

    const fetchAllData = useCallback(async () => {
        setIsLoading(true);
        try {
            const [chipsResponse, logsResponse] = await Promise.all([
                fetch(`${API_BASE_URL}/api/chips`),
                fetch(`${API_BASE_URL}/api/logs`),
            ]);
            if (!chipsResponse.ok) throw new Error('Failed to fetch chips');
            if (!logsResponse.ok) throw new Error('Failed to fetch logs');

            const chipsData: Chip[] = await chipsResponse.json();
            const logsData: AccessLog[] = await logsResponse.json();

            setChips(chipsData);
            setLogs(logsData);

            if (logsData.length > 0) {
                latestLogId.current = logsData[0].id;
            }
        } catch (error) {
            console.error(error);
            showToast('Error fetching data.', 'error');
        } finally {
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        const interval = setInterval(async () => {
            try {
                const response = await fetch(`${API_BASE_URL}/api/logs?limit=1`);
                if (!response.ok) return;
                const latestLogs: AccessLog[] = await response.json();

                if (latestLogs.length > 0 && latestLogs[0].id !== latestLogId.current) {
                    showToast('New activity detected. Refreshing...', 'success');
                    fetchAllData();
                }
            } catch (error) {
                console.warn('Polling error:', error);
            }
        }, 5000);

        return () => clearInterval(interval);
    }, [fetchAllData]);

    useEffect(() => {
        fetchAllData();
    }, [fetchAllData]);

    const handleAddChip = useCallback(async (newChip: Omit<Chip, 'id'>) => {
        try {
            const response = await fetch(`${API_BASE_URL}/api/chips`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(newChip),
            });
            if (!response.ok) throw new Error('Failed to add chip');
            showToast(`Chip for ${newChip.name} added successfully.`, 'success');
            fetchAllData();
        } catch (error) {
            console.error(error);
            showToast('Error adding chip.', 'error');
        }
    }, [fetchAllData]);

    const handleUpdateChip = useCallback(async (updatedChip: Chip) => {
        try {
            const response = await fetch(`${API_BASE_URL}/api/chips/${updatedChip.id}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(updatedChip),
            });
            if (!response.ok) throw new Error('Failed to update chip');
            showToast(`Chip for ${updatedChip.name} updated successfully.`, 'success');
            fetchAllData();
        } catch (error) {
            console.error(error);
            showToast('Error updating chip.', 'error');
        }
    }, [fetchAllData]);

    const handleDeleteChip = useCallback(async (chipId: number) => {
        try {
            const response = await fetch(`${API_BASE_URL}/api/chips/${chipId}`, {
                method: 'DELETE',
            });
            if (!response.ok) throw new Error('Failed to delete chip');
            showToast('Chip deleted successfully.', 'success');
            fetchAllData();
        } catch (error) {
            console.error(error);
            showToast('Error deleting chip.', 'error');
        }
    }, [fetchAllData]);

    const handleManualOverride = useCallback(async () => {
        try {
            const response = await fetch(`${API_BASE_URL}/api/manual-override`, {
                 method: 'GET',
            });
             if (!response.ok) throw new Error('Server did not acknowledge override request.');

            showToast('Unlock command sent to server.', 'success');
            // Refresh logs after a short delay to see the override event
            setTimeout(fetchAllData, 1000);
        } catch (error) {
            console.error(error);
            showToast('Error sending override command.', 'error');
        }
    }, [fetchAllData]);

    const handleRefresh = useCallback(() => {
        showToast('Refreshing data...', 'success');
        fetchAllData();
    }, [fetchAllData]);

    const renderContent = () => {
        if (isLoading) {
            return (
                <div className="flex items-center justify-center h-full">
                    <div className="text-lg font-semibold text-gray-600 dark:text-gray-400 animate-pulse">Loading Dashboard...</div>
                </div>
            );
        }

        switch (activeTab) {
            case 'dashboard':
                return <DashboardHome onManualOverride={handleManualOverride} logs={logs} chips={chips} onRefresh={handleRefresh} />;
            case 'chips':
                return <ChipManagement 
                            chips={chips} 
                            onAddChip={handleAddChip}
                            onUpdateChip={handleUpdateChip}
                            onDeleteChip={handleDeleteChip}
                        />;
            case 'logs':
                return <LogsViewer logs={logs} onRefresh={handleRefresh} />;
            default:
                return null;
        }
    };

    return (
        <div className="flex flex-col md:flex-row min-h-screen">
            <Header activeTab={activeTab} setActiveTab={setActiveTab} onLogout={onLogout} theme={theme} setTheme={setTheme} />
            <main className="flex-1 p-4 sm:p-6 md:p-8 bg-brand-light dark:bg-brand-darker overflow-y-auto">
                {renderContent()}
            </main>
            {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
        </div>
    );
};

interface DashboardHomeProps {
    onManualOverride: () => void;
    logs: AccessLog[];
    chips: Chip[];
    onRefresh: () => void;
}

const DashboardHome: React.FC<DashboardHomeProps> = ({ onManualOverride, logs, chips, onRefresh }) => {
    const recentLogs = logs.slice(0, 5);

    return (
        <div>
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Dashboard</h1>
                 <button onClick={onRefresh} className="p-2 rounded-full text-gray-500 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors">
                    <RefreshIcon className="h-5 w-5"/>
                </button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-6">
                <div className="bg-white dark:bg-brand-dark p-6 rounded-lg shadow-md">
                    <h3 className="font-semibold text-lg text-gray-700 dark:text-gray-300">Total Chips</h3>
                    <p className="text-3xl font-bold text-primary-600 dark:text-primary-400 mt-2">{chips.length}</p>
                </div>
                <div className="bg-white dark:bg-brand-dark p-6 rounded-lg shadow-md">
                    <h3 className="font-semibold text-lg text-gray-700 dark:text-gray-300">Allowed Chips</h3>
                    <p className="text-3xl font-bold text-green-500 mt-2">{chips.filter(c => c.is_allowed).length}</p>
                </div>
                <div className="bg-white dark:bg-brand-dark p-6 rounded-lg shadow-md">
                    <h3 className="font-semibold text-lg text-gray-700 dark:text-gray-300">Total Logs Today</h3>
                    <p className="text-3xl font-bold text-yellow-500 mt-2">{logs.filter(l => new Date(l.timestamp).toDateString() === new Date().toDateString()).length}</p>
                </div>
            </div>

            <div className="bg-white dark:bg-brand-dark p-6 rounded-lg shadow-md mb-6">
                <h2 className="text-xl font-semibold text-gray-800 dark:text-white mb-4">Manual Override</h2>
                <p className="text-gray-600 dark:text-gray-400 mb-4">Immediately unlock the main door. This action will be logged.</p>
                <button
                    onClick={onManualOverride}
                    className="flex items-center justify-center gap-2 px-6 py-3 text-white font-semibold bg-red-600 rounded-lg hover:bg-red-700 transition-colors focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-offset-2 dark:focus:ring-offset-gray-800"
                >
                    <LockOpenIcon className="h-5 w-5" />
                    Unlock Door
                </button>
            </div>
             <div className="bg-white dark:bg-brand-dark p-6 rounded-lg shadow-md">
                <h2 className="text-xl font-semibold text-gray-800 dark:text-white mb-4">Recent Activity</h2>
                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                        <thead>
                           <tr className="border-b dark:border-gray-700">
                                <th className="p-2 text-sm font-semibold text-gray-600 dark:text-gray-400">Timestamp</th>
                                <th className="p-2 text-sm font-semibold text-gray-600 dark:text-gray-400">Name</th>
                                <th className="p-2 text-sm font-semibold text-gray-600 dark:text-gray-400">Result</th>
                           </tr>
                        </thead>
                        <tbody>
                            {recentLogs.length > 0 ? recentLogs.map(log => (
                               <tr key={log.id} className="border-b dark:border-gray-700 last:border-b-0">
                                    <td className="p-2 text-gray-600 dark:text-gray-300">{new Date(log.timestamp).toLocaleString()}</td>
                                    <td className="p-2 text-gray-600 dark:text-gray-300">{log.name}</td>
                                    <td className="p-2"><span className={`px-2 py-1 text-xs font-semibold rounded-full ${
                                        log.result.startsWith('GRANTED') ? 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-300' : 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-300'
                                    }`}>{log.result}</span></td>
                               </tr>
                            )) : (
                                <tr>
                                    <td colSpan={3} className="p-4 text-center text-gray-500 dark:text-gray-400">No recent activity.</td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

export default Dashboard;

import React from 'react';
import { DashboardIcon, UsersIcon, ClipboardIcon, LogoutIcon, SunIcon, MoonIcon, DesktopIcon } from './icons';
import { Theme } from '../App';

interface HeaderProps {
    activeTab: 'dashboard' | 'chips' | 'logs';
    setActiveTab: (tab: 'dashboard' | 'chips' | 'logs') => void;
    onLogout: () => void;
    theme: Theme;
    setTheme: (theme: Theme) => void;
}

const NavItem: React.FC<{
    icon: React.ReactNode;
    label: string;
    isActive: boolean;
    onClick: () => void;
}> = ({ icon, label, isActive, onClick }) => {
    return (
        <button
            onClick={onClick}
            className={`flex items-center w-full px-4 py-3 text-sm font-medium transition-colors duration-150 rounded-lg ${
                isActive
                    ? 'bg-primary-500 text-white'
                    : 'text-gray-600 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-gray-700'
            }`}
        >
            {icon}
            <span className="ml-4">{label}</span>
        </button>
    );
};

export const Header: React.FC<HeaderProps> = ({ activeTab, setActiveTab, onLogout, theme, setTheme }) => {
    const themes: Theme[] = ['light', 'dark', 'system'];

    const handleThemeChange = () => {
        const currentIndex = themes.indexOf(theme);
        const nextIndex = (currentIndex + 1) % themes.length;
        setTheme(themes[nextIndex]);
    };

    const themeIcon = {
        light: <SunIcon className="h-5 w-5" />,
        dark: <MoonIcon className="h-5 w-5" />,
        system: <DesktopIcon className="h-5 w-5" />,
    }[theme];

    return (
        <aside className="w-full md:w-64 flex-shrink-0 bg-white dark:bg-brand-dark shadow-lg md:shadow-none">
            <div className="py-4 px-6 h-full flex flex-col">
                <div className="flex items-center justify-center md:justify-start py-2">
                    <img 
                        src="https://www.gypridilna.cz/wp-content/uploads/2024/10/Navrh_bez_nazvu__1_-removebg-preview.png" 
                        alt="Logo"
                        className="h-12 w-auto"
                    />
                </div>
                <nav className="mt-8 flex-1 space-y-2">
                    <NavItem 
                        icon={<DashboardIcon className="h-5 w-5" />}
                        label="Dashboard"
                        isActive={activeTab === 'dashboard'}
                        onClick={() => setActiveTab('dashboard')}
                    />
                    <NavItem
                        icon={<UsersIcon className="h-5 w-5" />}
                        label="Chip Management"
                        isActive={activeTab === 'chips'}
                        onClick={() => setActiveTab('chips')}
                    />
                    <NavItem
                        icon={<ClipboardIcon className="h-5 w-5" />}
                        label="Access Logs"
                        isActive={activeTab === 'logs'}
                        onClick={() => setActiveTab('logs')}
                    />
                </nav>
                <div className="mt-auto space-y-2">
                     <button
                        onClick={handleThemeChange}
                        className="flex items-center w-full px-4 py-3 text-sm font-medium text-gray-600 dark:text-gray-400 rounded-lg hover:bg-gray-200 dark:hover:bg-gray-700 capitalize"
                    >
                        {themeIcon}
                        <span className="ml-4">Theme: {theme}</span>
                    </button>
                     <button
                        onClick={onLogout}
                        className="flex items-center w-full px-4 py-3 text-sm font-medium text-gray-600 dark:text-gray-400 rounded-lg hover:bg-gray-200 dark:hover:bg-gray-700"
                    >
                        <LogoutIcon className="h-5 w-5" />
                        <span className="ml-4">Logout</span>
                    </button>
                </div>
            </div>
        </aside>
    );
};

